using System;using System.IO;using System.Security.Cryptography;using System.Windows.Forms;
namespace SargasPC {
 public enum FeedAccessState { Missing, Invalid, Unreadable, Stored }
 public static class FeedAccessPolicy {
  public static FeedAccessState Evaluate(string key){if(string.IsNullOrEmpty(key))return FeedAccessState.Missing;try{Data.Token(key);return FeedAccessState.Stored;}catch(IOException){return FeedAccessState.Invalid;}}
  public static string Explain(FeedAccessState state){switch(state){case FeedAccessState.Stored:return "Auth-Key išsaugotas; formatas tinkamas. Galiojimas tiekėjo pusėje dar nepatvirtintas.";case FeedAccessState.Invalid:return "Auth-Key formatas netinkamas. Atverkite „Įvesti / pakeisti raktą…“ ir įrašykite savo MalwareBazaar Auth-Key be tarpų ar naujų eilučių.";case FeedAccessState.Unreadable:return "Išsaugoto rakto nepavyko perskaityti šioje paskyroje. Ryšio nuostatose pašalinkite sugadintą raktų įrašą ir išsaugokite raktus iš naujo. Šalinimas pašalina abu ryšio raktus.";default:return "MalwareBazaar Auth-Key neįvestas. Atverkite „Įvesti / pakeisti raktą…“ ir įrašykite savo tiekėjo suteiktą Auth-Key trečiame lauke.";}}
  public static string NetworkError(bool feed,int code){if(feed&&(code==401||code==403))return "MalwareBazaar atmetė prieigą (HTTP "+code+"). Patikrinkite savo Auth-Key ir tiekėjo suteiktas teises per „Atnaujinti… → Papildomos MalwareBazaar sumos“. Tai ne ClamAV bazių atnaujinimo klaida.";return feed?"MalwareBazaar užklausa nepatvirtinta. Patikrinkite internetą ir tiekėjo pasiekiamumą. Išsaugotas raktas savaime nepatvirtina jo galiojimo.":"Tinklo patikra nepatvirtinta. Patikrinkite prieigą, HTTPS ir paslaugos būseną.";}
  public static string ResponseError(string status){return status=="illegal_auth_key"||status=="no_auth_key"||status=="invalid_auth_key"?NetworkError(true,401):"MalwareBazaar grąžino nepatvirtintą atsakymą. Papildomos sumos neatnaujintos; ClamAV bazės atnaujinamos atskirai.";}
 }
 public sealed partial class Core {
  public FeedAccessState FeedAccess(){try{var keys=ReadKeys();string key;return FeedAccessPolicy.Evaluate(keys!=null&&keys.TryGetValue("api",out key)?key:null);}catch(Exception e) when(e is IOException||e is UnauthorizedAccessException||e is CryptographicException||e is FormatException||e is ArgumentException||e is InvalidOperationException){return FeedAccessState.Unreadable;}}
  public string RequireFeedKey(){var state=FeedAccess();if(state!=FeedAccessState.Stored)throw new IOException("Papildomos MalwareBazaar sumos neatnaujintos. "+FeedAccessPolicy.Explain(state)+" ClamAV bazėms šio rakto nereikia.");return Key("api");}
 }
 public sealed partial class Window {
  private void FeedDialog(){using(var d=new Form{Text="Papildomos MalwareBazaar sumos",Width=780,Height=560,StartPosition=FormStartPosition.CenterParent}){var state=core.FeedAccess();var layout=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(16),FlowDirection=FlowDirection.TopDown,WrapContents=false};var note=new Label{Width=710,Height=220,Text="Tai papildomas žinomų SHA-256 sumų šaltinis. ClamAV virusų bazės atnaujinamos atskiru mygtuku ir šio Auth-Key nereikalauja.\r\n\r\n"+FeedAccessPolicy.Explain(state)+"\r\n\r\nĮvedimas tik išsaugo raktą šiai Windows paskyrai. Užklausa siunčiama tik pasirinkus sumų atnaujinimą ir patvirtinus. Rakto į ataskaitas nekelkite."};var keys=new Button{Width=710,Height=55,Text="Įvesti / pakeisti raktą…"};keys.Click+=(s,e)=>{d.Close();Network();};var recent=new Button{Width=710,Height=55,Text="Atsisiųsti 100 naujausių sumų…",Enabled=state==FeedAccessState.Stored};recent.Click+=(s,e)=>{d.Close();StartFeed(false);};var hour=new Button{Width=710,Height=55,Text="Papildyti paskutinės valandos sumomis…",Enabled=state==FeedAccessState.Stored};hour.Click+=(s,e)=>{d.Close();StartFeed(true);};layout.Controls.AddRange(new Control[]{note,keys,recent,hour});d.Controls.Add(layout);ThemeDialog(d);d.ShowDialog(this);}}
  private void StartFeed(bool hour){if(busy)return;if(core.FeedAccess()!=FeedAccessState.Stored){FeedDialog();return;}if(Confirm("Papildomos MalwareBazaar sumos", "Tiekėjas gaus jūsų Auth-Key ir IP. "+(hour?"Užklausiami paskutinių 60 minučių įrašai.":"Užklausiama tik 100 naujausių įrašų, ne visa grėsmių bazė.")+" Jūsų failai ar jų sumos nesiunčiami. ClamAV bazės šiuo veiksmu neatnaujinamos."))Run(hour?"MalwareBazaar: valandos sumų papildymas":"MalwareBazaar: 100 naujausių sumų",()=>core.UpdateFeed(hour));}
 }
}
